    // Hidden games
    "Games hidden from the library with HIDE in their menu. Tap one to show it in the library again." to Tr(ja = "メニューの かくすで ライブラリから かくした ゲームです。 タップすると また ライブラリに でます。", fr = "Jeux masqués de la bibliothèque avec MASQUER dans leur menu. Touchez-en un pour le réafficher dans la bibliothèque.", de = "Mit AUSBLENDEN in ihrem Menü aus der Bibliothek entfernte Spiele. Tippe auf eins, um es wieder in der Bibliothek zu zeigen.", it = "Giochi nascosti dalla libreria con NASCONDI nel loro menu. Toccane uno per mostrarlo di nuovo nella libreria.", es = "Juegos ocultados de la biblioteca con OCULTAR en su menú. Toca uno para volver a mostrarlo en la biblioteca.", br = "Jogos ocultados da biblioteca com OCULTAR no menu deles. Toque em um para mostrá-lo de novo na biblioteca.", pt = "Jogos ocultados da biblioteca com OCULTAR no seu menu. Toque num para o voltar a mostrar na biblioteca."),
    "NO HIDDEN GAMES" to Tr(ja = "かくした ゲームは ありません", fr = "AUCUN JEU MASQUÉ", de = "KEINE VERSTECKTEN SPIELE", it = "NESSUN GIOCO NASCOSTO", es = "NINGÚN JUEGO OCULTO", br = "NENHUM JOGO OCULTO", pt = "NENHUM JOGO OCULTO"),
    "SHOW" to Tr(ja = "ひょうじ", fr = "AFFICHER", de = "ZEIGEN", it = "MOSTRA", es = "MOSTRAR", br = "MOSTRAR", pt = "MOSTRAR"),

    // Cover art
    "Library covers are fetched once per ROM and kept on-device — nothing is bundled in the app. RetroAchievements has box art for every game with a set, SteamGridDB icons for FireRed, Emerald and the supported hacks; box art wins where there are both. Each needs your own free key: tap GET KEY, copy it from that page, paste it below and tap SAVE. Long-press a game for REPLACE COVER to pick another." to Tr(ja = "ライブラリの カバーは ROMごとに 1かい とってきて たんまつに ほぞんします — アプリには はいっていません。 RetroAchievementsには セットの ある ゲーム すべての パッケージ、 SteamGridDBには FireRed、Emerald と たいおう ハックの アイコンが あります。 りょうほう あれば パッケージを つかいます。 どちらも じぶんの むりょうの キーが ひつようです: 「キーを とる」を タップし ページの キーを コピーして したに はりつけ セーブを タップ。 ゲームを ながおしして「カバーを かえる」で べつの ものを えらべます。", fr = "Les jaquettes sont téléchargées une fois par ROM et gardées sur l'appareil — rien n'est inclus dans l'appli. RetroAchievements a la boîte de chaque jeu doté d'un set, SteamGridDB des icônes pour FireRed, Emerald et les hacks pris en charge ; la boîte l'emporte quand il y a les deux. Chacun demande votre propre clé gratuite : touchez OBTENIR LA CLÉ, copiez-la sur cette page, collez-la ci-dessous et touchez SAUVER. Appui long sur un jeu, puis CHANGER JAQUETTE pour en choisir une autre.", de = "Bibliothek-Cover werden einmal pro ROM geladen und auf dem Gerät gespeichert — nichts davon steckt in der App. RetroAchievements hat die Verpackung jedes Spiels mit einem Set, SteamGridDB Icons für FireRed, Emerald und die unterstützten Hacks; gibt es beides, gewinnt die Verpackung. Beide brauchen deinen eigenen kostenlosen Schlüssel: Tippe auf SCHLÜSSEL HOLEN, kopiere ihn von der Seite, füge ihn unten ein und tippe auf SICHERN. Halte ein Spiel gedrückt und wähle COVER ERSETZEN für ein anderes.", it = "Le copertine vengono scaricate una volta per ROM e salvate sul dispositivo — nulla è incluso nell'app. RetroAchievements ha la confezione di ogni gioco con un set, SteamGridDB icone per FireRed, Emerald e gli hack supportati; se ci sono entrambe vince la confezione. Ognuno richiede la tua chiave gratuita: tocca OTTIENI CHIAVE, copiala da quella pagina, incollala qui sotto e tocca SALVA. Tieni premuto un gioco e scegli CAMBIA COPERTINA per sceglierne un'altra.", es = "Las portadas se descargan una vez por ROM y se guardan en el dispositivo — nada viene incluido en la app. RetroAchievements tiene la caja de cada juego con un set, SteamGridDB iconos para FireRed, Emerald y los hacks compatibles; si hay ambas, gana la caja. Cada uno necesita tu propia clave gratis: toca OBTENER CLAVE, cópiala de esa página, pégala abajo y toca GUARDAR. Mantén pulsado un juego y elige CAMBIAR PORTADA para escoger otra.", br = "As capas da biblioteca são baixadas uma vez por ROM e ficam no aparelho: nada vem incluído no app. O RetroAchievements tem a caixa de todo jogo com um set, o SteamGridDB ícones para FireRed, Emerald e os hacks suportados; a caixa vence quando há os dois. Cada um precisa da sua própria chave grátis: toque em OBTER CHAVE, copie-a daquela página, cole abaixo e toque em SALVAR. Toque e segure um jogo e escolha TROCAR CAPA para pegar outra.", pt = "As capas da biblioteca são transferidas uma vez por ROM e ficam no dispositivo: nada vem incluído na app. O RetroAchievements tem a caixa de cada jogo com um set, o SteamGridDB ícones para FireRed, Emerald e os hacks suportados; a caixa ganha quando há as duas. Cada um precisa da sua chave gratuita: toque em OBTER CHAVE, copie-a dessa página, cole-a abaixo e toque em GUARDAR. Mantenha um jogo premido e escolha TROCAR CAPA para escolher outra."),
    "{0} API KEY" to Tr(ja = "{0} APIキー", fr = "CLÉ API {0}", de = "{0}-API-SCHLÜSSEL", it = "CHIAVE API {0}", es = "CLAVE API DE {0}", br = "CHAVE API {0}", pt = "CHAVE API {0}"),
    "{0} WEB API KEY" to Tr(ja = "{0} Web APIキー", fr = "CLÉ WEB API {0}", de = "{0}-WEB-API-SCHLÜSSEL", it = "CHIAVE WEB API {0}", es = "CLAVE WEB API DE {0}", br = "CHAVE WEB API {0}", pt = "CHAVE WEB API {0}"),
    "CLEAR" to Tr(ja = "クリア", fr = "EFFACER", de = "LEEREN", it = "CANCELLA", es = "BORRAR", br = "LIMPAR", pt = "LIMPAR"),
    "REPLACE ALL" to Tr(ja = "ぜんぶ いれかえ", fr = "TOUT REMPLACER", de = "ALLE ERSETZEN", it = "SOSTITUISCI TUTTE", es = "REEMPLAZAR TODAS", br = "SUBSTITUIR TODAS", pt = "SUBSTITUIR TODAS"),
    "REPLACE ALL COVERS?" to Tr(ja = "カバーを ぜんぶ いれかえますか?", fr = "REMPLACER TOUTES LES JAQUETTES ?", de = "ALLE COVER ERSETZEN?", it = "SOSTITUIRE TUTTE LE COPERTINE?", es = "¿REEMPLAZAR TODAS LAS PORTADAS?", br = "SUBSTITUIR TODAS AS CAPAS?", pt = "SUBSTITUIR TODAS AS CAPAS?"),
    "Fetches new art from SteamGridDB for every ROM, replacing current covers (manually set ones too). A ROM with no art found keeps its cover." to Tr(ja = "SteamGridDBから すべての ROMの あたらしい がぞうを とってきて いまの カバーと いれかえます(じぶんで えらんだ ものも)。 がぞうが みつからない ROMは いまの カバーの ままです。", fr = "Récupère de nouvelles images sur SteamGridDB pour chaque ROM et remplace les jaquettes actuelles (même celles choisies à la main). Une ROM sans image trouvée garde sa jaquette.", de = "Lädt für jede ROM neue Bilder von SteamGridDB und ersetzt die aktuellen Cover (auch manuell gesetzte). Eine ROM ohne gefundenes Bild behält ihr Cover.", it = "Scarica nuove immagini da SteamGridDB per ogni ROM, sostituendo le copertine attuali (anche quelle scelte a mano). Una ROM senza immagini trovate mantiene la sua copertina.", es = "Descarga nuevas imágenes de SteamGridDB para cada ROM y reemplaza las portadas actuales (también las elegidas a mano). Una ROM sin imágenes encontradas conserva su portada.", br = "Baixa novas imagens do SteamGridDB para cada ROM, substituindo as capas atuais (também as escolhidas à mão). Uma ROM sem imagem encontrada mantém sua capa.", pt = "Transfere novas imagens do SteamGridDB para cada ROM, substituindo as capas atuais (também as escolhidas à mão). Uma ROM sem imagem encontrada mantém a sua capa."),
    "REPLACE" to Tr(ja = "いれかえる", fr = "REMPLACER", de = "ERSETZEN", it = "SOSTITUISCI", es = "REEMPLAZAR", br = "SUBSTITUIR", pt = "SUBSTITUIR"),

    // Hotkeys / game buttons
    "Tap a hotkey, then press one or more keys/buttons together and release — e.g. hold Select and tap R1 for a chord. BACK cancels." to Tr(ja = "ホットキーを タップして、 キーや ボタンを 1つか いくつか いっしょに おして はなします — たとえば Selectを おしたまま R1を おすと くみあわせに なります。 BACKで キャンセル。", fr = "Touchez un raccourci, puis appuyez sur une ou plusieurs touches ensemble et relâchez — ex. maintenez Select et appuyez sur R1 pour une combinaison. BACK annule.", de = "Tippe auf einen Hotkey, drücke dann eine oder mehrere Tasten zusammen und lass los — z. B. Select halten und R1 tippen für eine Kombination. BACK bricht ab.", it = "Tocca un tasto rapido, poi premi insieme uno o più tasti e rilascia — es. tieni Select e premi R1 per una combinazione. BACK annulla.", es = "Toca un atajo, luego pulsa una o más teclas a la vez y suelta — p. ej. mantén Select y pulsa R1 para una combinación. BACK cancela.", br = "Toque em um atalho, depois aperte uma ou mais teclas/botões juntos e solte: ex. segure Select e toque em R1 para uma combinação. BACK cancela.", pt = "Toque num atalho, depois prima uma ou mais teclas/botões juntos e solte: ex. mantenha Select e prima R1 para uma combinação. BACK cancela."),
    "PRESS KEYS…" to Tr(ja = "キーを おして…", fr = "APPUYEZ…", de = "TASTEN DRÜCKEN…", it = "PREMI I TASTI…", es = "PULSA TECLAS…", br = "APERTE TECLAS…", pt = "PRIMA TECLAS…"),
    "Which physical button is each GBA button. The D-pad and analog stick are fixed." to Tr(ja = "GBAの それぞれの ボタンに どの ボタンを つかうか。 じゅうじキーと スティックは かえられません。", fr = "Quel bouton physique correspond à chaque bouton GBA. La croix et le stick analogique sont fixes.", de = "Welche echte Taste jede GBA-Taste ist. Steuerkreuz und Analogstick sind fest.", it = "Quale tasto fisico corrisponde a ogni tasto GBA. Croce direzionale e levetta analogica sono fissi.", es = "Qué botón físico es cada botón de GBA. La cruceta y el stick analógico son fijos.", br = "Qual botão físico é cada botão do GBA. O direcional e o analógico são fixos.", pt = "Que botão físico é cada botão do GBA. A cruz direcional e o analógico são fixos."),
    "PRESS A BUTTON…" to Tr(ja = "ボタンを おして…", fr = "APPUYEZ SUR UN BOUTON…", de = "TASTE DRÜCKEN…", it = "PREMI UN TASTO…", es = "PULSA UN BOTÓN…", br = "APERTE UM BOTÃO…", pt = "PRIMA UM BOTÃO…"),
    "Press the button on your device. BACK cancels." to Tr(ja = "つかう ボタンを おしてください。 BACKで キャンセル。", fr = "Appuyez sur le bouton de votre appareil. BACK annule.", de = "Drücke die Taste an deinem Gerät. BACK bricht ab.", it = "Premi il tasto sul dispositivo. BACK annulla.", es = "Pulsa el botón en tu dispositivo. BACK cancela.", br = "Aperte o botão no seu aparelho. BACK cancela.", pt = "Prima o botão no seu dispositivo. BACK cancela."),
    "Hold the keys together, then let go. BACK cancels." to Tr(ja = "キーを いっしょに おして はなしてください。 BACKで キャンセル。", fr = "Maintenez les touches ensemble, puis relâchez. BACK annule.", de = "Halte die Tasten zusammen und lass dann los. BACK bricht ab.", it = "Tieni premuti i tasti insieme, poi rilascia. BACK annulla.", es = "Mantén las teclas a la vez y luego suelta. BACK cancela.", br = "Segure as teclas juntas e depois solte. BACK cancela.", pt = "Mantenha as teclas premidas juntas e depois solte. BACK cancela."),
