    "OVERLAYS ADDED" to Tr(ja = "オーバーレイを ついかしました", fr = "SURIMPRESSIONS AJOUTÉES", de = "OVERLAYS HINZUGEFÜGT", it = "OVERLAY AGGIUNTI", es = "SUPERPOSICIONES AÑADIDAS", br = "MOLDURAS ADICIONADAS", pt = "MOLDURAS ADICIONADAS"),
    "{0} is on. Games show it from now on." to Tr(ja = "{0}を つかいます。 これから ゲームに でます。", fr = "{0} est activée. Les jeux l'affichent désormais.", de = "{0} ist an. Spiele zeigen es ab jetzt.", it = "{0} è attivo. I giochi lo mostrano da ora.", es = "{0} está activada. Los juegos la muestran desde ahora.", br = "{0} está ativa. Os jogos a mostram a partir de agora.", pt = "{0} está ativa. Os jogos passam a mostrá-la."),
